import unittest

from solution import apply_revision, rollback_revision


EXPECTED = {"name": "reviewers", "kind": "references", "optional": True}


class RevisionTests(unittest.TestCase):
    def test_apply_appends_field_and_preserves_order(self):
        schema = {
            "Article": [{"name": "title", "kind": "text"}],
            "User": [{"name": "email", "kind": "text"}],
        }
        result = apply_revision(schema)
        self.assertEqual(list(result), ["Article", "User"])
        self.assertEqual(result["Article"], [schema["Article"][0], EXPECTED])
        self.assertEqual(result["User"], schema["User"])

    def test_apply_is_a_fully_independent_deep_copy(self):
        schema = {
            "Article": [{"name": "title", "kind": "text", "meta": {"tags": ["a"]}}],
            "Other": [{"name": "value", "kind": "text", "meta": {"x": [1]}}],
        }
        result = apply_revision(schema)
        self.assertIsNot(result, schema)
        self.assertIsNot(result["Article"], schema["Article"])
        self.assertIsNot(result["Article"][0], schema["Article"][0])
        self.assertIsNot(result["Other"][0]["meta"]["x"], schema["Other"][0]["meta"]["x"])
        result["Other"][0]["meta"]["x"].append(2)
        self.assertEqual(schema["Other"][0]["meta"]["x"], [1])
        schema["Article"][0]["meta"]["tags"].append("b")
        self.assertEqual(result["Article"][0]["meta"]["tags"], ["a"])

    def test_rollback_removes_only_exact_revision_field(self):
        schema = {
            "Article": [{"name": "title", "kind": "text"}, EXPECTED.copy(), {"name": "body", "kind": "text"}],
            "User": [{"name": "id", "kind": "integer"}],
        }
        before = {name: [field.copy() for field in fields] for name, fields in schema.items()}
        result = rollback_revision(schema)
        self.assertEqual(result, {
            "Article": [{"name": "title", "kind": "text"}, {"name": "body", "kind": "text"}],
            "User": [{"name": "id", "kind": "integer"}],
        })
        self.assertEqual(schema, before)
        self.assertIsNot(result["User"], schema["User"])
        self.assertIsNot(result["User"][0], schema["User"][0])

    def test_apply_rejects_missing_bad_article_or_existing_name(self):
        invalid = [
            {"Other": []},
            {"Article": ()},
            {"Article": [{"name": "reviewers", "kind": "anything"}]},
        ]
        for schema in invalid:
            with self.subTest(schema=schema):
                with self.assertRaises(ValueError):
                    apply_revision(schema)

    def test_rollback_requires_exact_descriptor(self):
        invalid = [
            {"Article": []},
            {"Article": [{"name": "reviewers", "kind": "references", "optional": False}]},
            {"Article": [{"name": "reviewers", "kind": "references", "optional": True, "extra": 1}]},
            {"Other": []},
            {"Article": ()},
        ]
        for schema in invalid:
            with self.subTest(schema=schema):
                with self.assertRaises(ValueError):
                    rollback_revision(schema)

    def test_rejects_non_mapping_and_non_dictionary_descriptors(self):
        for function in (apply_revision, rollback_revision):
            with self.subTest(function=function.__name__):
                with self.assertRaises(ValueError):
                    function([])
                with self.assertRaises(ValueError):
                    function({"Article": ["not a descriptor"]})


if __name__ == "__main__":
    unittest.main()

